const { Server } = require('@tus/server');
const { S3Store } = require('@tus/s3-store');
const { S3Client } = require('@aws-sdk/client-s3');
const { PrismaClient } = require('@prisma/client');

const prisma = new PrismaClient();
const s3 = new S3Client({ region: 'us-west-2' });

const tus = new Server({
  path: '/tus/contracts',
  datastore: new S3Store({ s3ClientConfig: { bucket: 'vault-contracts' } }),
  onUploadFinish: async (req, res, upload) => {
    const { contractId, companyId } = upload.metadata;

    if (!req.user || req.user.companyId !== companyId) {
      throw { status_code: 403, body: 'Forbidden: cannot upload contract for another company' };
    }

    await prisma.corporateContract.create({
      data: {
        id: contractId,
        companyId: companyId,
        storageKey: upload.id,
        uploadedAt: new Date(),
      }
    });
    return res;
  }
});
